package app.relaydrop;

import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.net.*;
import android.os.*;
import android.provider.OpenableColumns;
import org.json.*;
import javax.net.ssl.SSLException;
import java.io.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

/** Foreground uploads survive Activity closure; only completely staged originals are restartable. */
public final class UploadQueueService extends Service {
  static final String ENQUEUE="ENQUEUE",PAUSE="PAUSE",RESUME="RESUME",CANCEL="CANCEL",WAKE="WAKE";
  private static final int NOTICE=31;
  private static final long MAX_FILE=20L*1024*1024*1024,RESERVE=32L*1024*1024;
  private final ExecutorService commands=Executors.newSingleThreadExecutor();
  private TransferQueueStore store;
  private NotificationManager notifications;
  private ConnectivityManager connectivity;
  private ConnectivityManager.NetworkCallback network;
  private PowerManager.WakeLock wake;
  private volatile boolean destroyed;
  private final java.util.concurrent.atomic.AtomicInteger pendingCommands=new java.util.concurrent.atomic.AtomicInteger();
  private volatile int lastStartId;
  private volatile long queueRevision;
  private static final class PayloadFailure extends IOException {PayloadFailure(String message){super(message);}}
  private volatile Thread worker;
  private volatile ShareTransport active;
  private volatile InputStream activeInput;
  private volatile String currentId;
  private long notified,journaled;
  private final Object signal=new Object();
  static void control(Context context,String action,String id){Intent intent=new Intent(context,UploadQueueService.class).setAction(action);if(id!=null)intent.putExtra("id",id);context.startForegroundService(intent);}
  @Override public void onCreate(){super.onCreate();notifications=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);notifications.createNotificationChannel(new NotificationChannel("relay-transfers","后台传输任务",NotificationManager.IMPORTANCE_LOW));startForeground(NOTICE,notice("正在恢复后台传输…",0,0,false));try{store=TransferQueueStore.get(this);PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);wake=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"RelayDrop:upload");connectivity=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);network=new ConnectivityManager.NetworkCallback(){@Override public void onAvailable(Network n){if(!destroyed)try{commands.execute(()->{try{forEach("waiting",j->j.put("nextAttemptAt",0));synchronized(UploadQueueService.this){queueRevision++;kick();}synchronized(signal){signal.notifyAll();}}catch(Exception ignored){}});}catch(RejectedExecutionException ignored){}}};connectivity.registerDefaultNetworkCallback(network);}catch(Exception error){notifications.notify(NOTICE,notice(message(error),0,0,true));stopSelf();}}
  @Override public int onStartCommand(Intent intent,int flags,int startId){startForeground(NOTICE,notice("正在处理后台传输…",0,0,false));if(store==null)return START_NOT_STICKY;lastStartId=startId;pendingCommands.incrementAndGet();commands.execute(()->{try{String action=intent==null?WAKE:intent.getAction();if(ENQUEUE.equals(action))enqueue(intent);else if(PAUSE.equals(action)||RESUME.equals(action)||CANCEL.equals(action))command(action,intent.getStringExtra("id"));}catch(Exception error){notifications.notify(NOTICE,notice(message(error),0,0,true));}finally{synchronized(this){queueRevision++;pendingCommands.decrementAndGet();kick();}}});return START_STICKY;}
  private void enqueue(Intent intent)throws Exception{
    String serverId=intent.getStringExtra("serverId"),fingerprint=intent.getStringExtra("fingerprint"),target=intent.getStringExtra("targetId"),text=intent.getStringExtra("text");ShareConnectionStore.Entry connection=new ShareConnectionStore(this).findId(serverId),local=ShareConnectionStore.local();if(local!=null&&local.serverId.equals(serverId))connection=local;if(connection==null||!connection.fingerprint.equals(fingerprint))throw new IOException("可信连接已变化，请重新确认接收设备。");if(target!=null&&!target.matches("host|[a-fA-F0-9-]{36}"))throw new IOException("接收范围无效。");
    ArrayList<Uri> sources=intent.getParcelableArrayListExtra("uris");LinkedHashSet<Uri> unique=new LinkedHashSet<>();if(sources!=null)unique.addAll(sources);if(unique.size()>100)throw new IOException("一次最多添加 100 个文件。");for(Uri uri:unique)if(uri==null||!"content".equals(uri.getScheme())||uri.getAuthority()==null)throw new IOException("文件需要系统授权的内容地址。");if(text!=null&&(text.length()>20000||text.indexOf('\0')>=0))throw new IOException("文字内容无效。");
    String folderId=intent.getStringExtra("folderId"),tree=intent.getStringExtra("folderTree");if(folderId!=null&&!folderId.matches("[a-fA-F0-9-]{36}"))throw new IOException("共享目录编号无效。");if(target!=null&&folderId!=null)throw new IOException("定向发送不能放入共享目录。");boolean skip=intent.getBooleanExtra("skipDuplicates",false);
    JSONObject confirmed=new ShareTransport(connection).request("/api/state","GET",null);ShareDirectorySupport.verifyIdentity(confirmed,connection);String deviceId=confirmed.getJSONObject("device").getString("id");if(!deviceId.equals(intent.getStringExtra("deviceId")))throw new IOException("配对身份已变化，请重新确认发送。");JSONArray incoming=new JSONArray();String batch=UUID.randomUUID().toString();if(text!=null&&!text.trim().isEmpty())incoming.put(job(batch,connection,target,"text").put("text",text).put("name","文字 / 链接").put("status","queued"));for(Uri uri:unique){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}incoming.put(job(batch,connection,target,"file").put("sourceUri",uri.toString()).put("name","正在准备原件").put("status","importing").put("folderId",folderId==null?JSONObject.NULL:folderId).put("skipDuplicates",skip));}
    if(tree!=null){if(target!=null)throw new IOException("整个文件夹仅支持共享文件池。");Uri uri=Uri.parse(tree);try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}for(SafTreeFiles.Entry item:SafTreeFiles.scan(getContentResolver(),uri)){JSONObject itemJob=job(batch,connection,null,item.directory?"folder":"file").put("name",item.path).put("relativePath",item.path).put("folderId",folderId==null?JSONObject.NULL:folderId).put("skipDuplicates",skip).put("status",item.directory?"queued":"importing");if(!item.directory)itemJob.put("sourceUri",item.uri.toString());incoming.put(itemJob);}}
    if(incoming.length()==0)throw new IOException("没有可发送的内容。");for(int n=0;n<incoming.length();n++)incoming.getJSONObject(n).put("deviceId",deviceId);store.add(incoming);
  }
  private JSONObject job(String batch,ShareConnectionStore.Entry entry,String target,String kind)throws Exception{String id=UUID.randomUUID().toString();return new JSONObject().put("id",id).put("clientId",id).put("batchId",batch).put("kind",kind).put("serverId",entry.serverId).put("fingerprint",entry.fingerprint).put("destination",entry.label).put("targetId",target==null?JSONObject.NULL:target).put("createdAt",System.currentTimeMillis()).put("updatedAt",System.currentTimeMillis()).put("offset",0).put("attempts",0);}
  private void forEach(String state,TransferQueueStore.Change change)throws Exception{JSONArray all=store.snapshot();for(int i=0;i<all.length();i++){JSONObject job=all.getJSONObject(i);if(state.equals(job.optString("status")))store.change(job.getString("id"),change);}}
  private void command(String action,String only)throws Exception{
    JSONArray jobs=store.snapshot();for(int i=0;i<jobs.length();i++){String id=jobs.getJSONObject(i).getString("id");if(only!=null&&!only.equals(id))continue;final boolean[] interrupt={false};store.change(id,j->interrupt[0]=QueueTransitions.control(j,action));
      if(CANCEL.equals(action)&&!id.equals(currentId)){store.partial(id).delete();store.payload(id).delete();}
      if(id.equals(currentId)&&interrupt[0]){ShareTransport transport=active;if(transport!=null)transport.cancel();if(CANCEL.equals(action)){InputStream input=activeInput;if(input!=null)new Thread(()->{try{input.close();}catch(Exception ignored){}},"queue-cancel-input").start();}}
    }synchronized(signal){signal.notifyAll();}
  }
  private synchronized void kick(){if(destroyed||worker!=null)return;worker=new Thread(this::runQueue,"relay-background-upload");worker.start();}
  private void runQueue(){try{while(!destroyed){long observedRevision=queueRevision;JSONArray jobs=store.snapshot();JSONObject selected=null;boolean waiting=false,paused=false;long nextWake=System.currentTimeMillis()+300000L;for(int i=0;i<jobs.length();i++){JSONObject job=jobs.getJSONObject(i);String state=job.optString("status");if("importing".equals(state)||"staged".equals(state)){selected=job;break;}}
      if(selected==null)for(int i=0;i<jobs.length();i++){JSONObject job=jobs.getJSONObject(i);String state=job.optString("status");if("paused".equals(state)||"blocked".equals(state)||"needs_source".equals(state)||"failed".equals(state))paused=true;if("queued".equals(state)||"waiting".equals(state)){waiting=true;nextWake=Math.min(nextWake,job.optLong("nextAttemptAt"));if(job.optLong("nextAttemptAt")<=System.currentTimeMillis()){selected=job;break;}}}
      if(selected==null){if(waiting){if(wake!=null&&wake.isHeld())wake.release();notifications.notify(NOTICE,notice("等待网络或中转站恢复，将自动重试",0,0,false));synchronized(signal){if(observedRevision==queueRevision)signal.wait(Math.max(100,Math.min(300000,nextWake-System.currentTimeMillis())));}continue;}if(pendingCommands.get()>0){synchronized(signal){signal.wait(50);}continue;}notifications.notify(NOTICE,notice(paused?"部分任务已暂停或需要处理，点击查看":"后台队列已处理完毕，点击查看结果",0,0,true));store.trim();final int idleStart=lastStartId;synchronized(this){if(pendingCommands.get()>0||observedRevision!=queueRevision)continue;worker=null;}new Handler(Looper.getMainLooper()).post(()->{synchronized(UploadQueueService.this){if(worker==null&&pendingCommands.get()==0&&lastStartId==idleStart){if(stopSelfResult(idleStart))stopForeground(false);}}});return;}
      currentId=selected.getString("id");if(wake!=null&&!wake.isHeld())wake.acquire(6*60*60*1000L);try{if("importing".equals(selected.optString("status")))stage(selected);else if("staged".equals(selected.optString("status")))finishStage(selected);else send(selected);}catch(Exception error){handleFailure(selected,error);}finally{active=null;activeInput=null;JSONObject latest=store.find(currentId);if(latest!=null&&TransferQueueStore.terminal(latest.optString("status"))){store.partial(currentId).delete();store.payload(currentId).delete();}currentId=null;}
    }}catch(Exception error){notifications.notify(NOTICE,notice(message(error),0,0,true));stopSelf();}finally{synchronized(this){if(worker==Thread.currentThread())worker=null;}}}
  private void check(String id,String expected)throws Exception{if(destroyed||!expected.equals(store.find(id).optString("status")))throw new IOException("任务已暂停或取消。");}
  private void stage(JSONObject job)throws Exception{
    String id=job.getString("id");check(id,"importing");Uri uri=Uri.parse(job.getString("sourceUri"));String name=null;long declared=-1;try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){int ni=c.getColumnIndex(OpenableColumns.DISPLAY_NAME),si=c.getColumnIndex(OpenableColumns.SIZE);if(ni>=0)name=c.getString(ni);if(si>=0&&!c.isNull(si))declared=c.getLong(si);}}String filename=safeName(name);if(declared>MAX_FILE)throw new IOException("文件超过 20 GiB 限制。");if(declared>0&&declared>store.directory.getUsableSpace()-RESERVE)throw new IOException("手机可用空间不足，无法完整保存待发送原件。");final long announced=declared;store.change(id,j->j.put("name",filename).put("declaredSize",announced));File part=store.partial(id);MessageDigest digest=MessageDigest.getInstance("SHA-256");long total=0;
    try(InputStream in=getContentResolver().openInputStream(uri);FileOutputStream out=new FileOutputStream(part)){if(in==null)throw new IOException("无法打开原文件。");activeInput=in;check(id,"importing");byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){check(id,"importing");if(total>MAX_FILE-n||store.directory.getUsableSpace()<RESERVE+n)throw new IOException("原文件过大或手机剩余空间不足。");out.write(b,0,n);digest.update(b,0,n);total+=n;progress("正在缓存原件："+filename,total,declared,id);}out.getFD().sync();}finally{activeInput=null;}
    check(id,"importing");if(declared>=0&&total!=declared)throw new IOException("来源文件长度发生变化，已拒绝发送。");final long size=total;final String hash=ShareTransport.hex(digest.digest());store.change(id,j->{if(!"importing".equals(j.optString("status")))throw new IOException("任务已取消。");j.put("size",size).put("sha256",hash).put("status","staged").remove("sourceUri");});finishStage(store.find(id));
  }
  private void finishStage(JSONObject job)throws Exception{String id=job.getString("id");File part=store.partial(id),ready=store.payload(id);if(!ready.isFile()&&(!part.isFile()||!part.renameTo(ready)))throw new IOException("无法保存完整的待发送原件。");store.change(id,j->{if(!"staged".equals(j.optString("status")))throw new IOException("任务已取消。");j.put("status",j.optBoolean("pauseAfterImport")?"paused":"queued").put("offset",0);});}
  private void send(JSONObject job)throws Exception{
    String id=job.getString("id");store.change(id,j->{if(!"queued".equals(j.optString("status"))&&!"waiting".equals(j.optString("status")))throw new IOException("任务已暂停。");j.put("status","sending").put("error",JSONObject.NULL);});check(id,"sending");ShareConnectionStore.Entry entry=new ShareConnectionStore(this).findId(job.getString("serverId")),local=ShareConnectionStore.local();if(local!=null&&local.serverId.equals(job.getString("serverId")))entry=local;if(entry==null||!entry.fingerprint.equals(job.getString("fingerprint")))throw new javax.net.ssl.SSLPeerUnverifiedException("可信设备身份已变化；请取消此任务并核对设备后重新分享。");if(entry.origin.startsWith("http://")&&local==null)throw new IOException("本机中转站尚未启动；请回首页创建中转站，再恢复任务。");entry=TrustedDiscovery.verifyOrReconnect(this,entry);check(id,"sending");ShareTransport client=new ShareTransport(entry);active=client;check(id,"sending");String target=job.isNull("targetId")?null:job.optString("targetId");
    JSONObject currentState=client.request("/api/state","GET",null);ShareDirectorySupport.verifyIdentity(currentState,entry);if(job.optString("deviceId").isEmpty()||!job.optString("deviceId").equals(currentState.getJSONObject("device").getString("id")))throw new javax.net.ssl.SSLPeerUnverifiedException("配对身份已改变或旧任务缺少身份记录；请重新分享原件。");String folderId=job.isNull("folderId")?null:job.optString("folderId");String relative=job.optString("relativePath",null);boolean directoryJob="folder".equals(job.optString("kind"));
    if(relative!=null){SafTreeFiles.path(relative);String directoryPath=directoryJob?relative:relative.contains("/")?relative.substring(0,relative.lastIndexOf('/')):"";if(!directoryPath.isEmpty()){JSONArray segments=new JSONArray();for(String p:directoryPath.split("/"))segments.put(p);folderId=client.request("/api/folders/ensure","POST",new JSONObject().put("parentId",folderId==null?JSONObject.NULL:folderId).put("path",segments)).getString("folderId");}}
    if("text".equals(job.optString("kind")))client.request("/api/notes","POST",new JSONObject().put("clientId",job.getString("clientId")).put("text",job.getString("text")).put("targetId",target==null?JSONObject.NULL:target));
    else if(!directoryJob){File source=store.payload(id);if(!source.isFile()||source.length()!=job.getLong("size"))throw new PayloadFailure("本机缓存不完整，请重新分享原件。");MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(source)){byte[] b=new byte[65536];int n;long count=0;while((n=in.read(b))!=-1){check(id,"sending");hash.update(b,0,n);count+=n;progress("核对缓存："+job.getString("name"),count,source.length(),id);}}if(!ShareTransport.hex(hash.digest()).equals(job.getString("sha256")))throw new PayloadFailure("本机缓存校验失败，已阻止发送，请重新分享原件。");boolean duplicate=false;if(job.optBoolean("skipDuplicates")&&!job.has("transferId")){try{JSONArray matches=client.request("/api/files/duplicates","POST",new JSONObject().put("sha256",job.getString("sha256")).put("size",source.length()).put("targetId",target==null?JSONObject.NULL:target).put("folderId",folderId==null?JSONObject.NULL:folderId)).getJSONArray("matches");if(matches.length()>0){duplicate=true;String existing=matches.getJSONObject(0).getString("id");store.change(id,j->j.put("resultNote","文件池已有相同原件，已跳过上传").put("existingFileId",existing));}}catch(ShareTransport.ApiFailure error){if(error.status!=404)throw error;}}
      if(!duplicate)client.upload(source,job.getString("name"),job.getString("sha256"),target,folderId,job.optString("transferId",null),(text,current,total)->progress(text,current,total,id),remote->store.change(id,j->{if(!"sending".equals(j.optString("status")))throw new IOException("任务已暂停。");j.put("transferId",remote);}));}
    store.change(id,j->{if(!"cancelled".equals(j.optString("status")))j.put("status","done").put("completedAt",System.currentTimeMillis()).put("offset",j.optLong("size")).put("error",JSONObject.NULL);});
  }
  private void handleFailure(JSONObject original,Exception error)throws Exception{String id=original.getString("id");JSONObject current=store.find(id);String state=current.optString("status");if("cancelled".equals(state)||"paused".equals(state))return;boolean importing="importing".equals(state)||"staged".equals(state)||error instanceof PayloadFailure;if(importing){store.partial(id).delete();store.payload(id).delete();store.change(id,j->{if(QueueTransitions.mayFail(j))j.put("status","needs_source").put("error",message(error));});return;}boolean identity=error instanceof SSLException||error.getCause() instanceof java.security.cert.CertificateException;boolean retry=error instanceof IOException&&!identity;if(error instanceof ShareTransport.ApiFailure){int status=((ShareTransport.ApiFailure)error).status;retry=status==408||status==429||status>=500||status==409&&("VERIFYING".equals(((ShareTransport.ApiFailure)error).code)||"OFFSET_MISMATCH".equals(((ShareTransport.ApiFailure)error).code));}final boolean retryable=retry;final String next=identity?"blocked":retry?"waiting":"failed";store.change(id,j->{if(!QueueTransitions.mayFail(j))return;int attempts=j.optInt("attempts")+1;j.put("status",next).put("error",message(error)).put("attempts",attempts);if(retryable)j.put("nextAttemptAt",System.currentTimeMillis()+Math.min(300000L,2000L*(1L<<Math.min(attempts,7))));});}
  private void progress(String message,long count,long total,String id){long now=System.currentTimeMillis();if(now-notified>350){notified=now;notifications.notify(NOTICE,notice(message,count,total,false));}if(now-journaled>1000){journaled=now;try{store.change(id,j->j.put("offset",count));}catch(Exception ignored){}}}
  private Notification notice(String text,long count,long total,boolean idle){Intent open=new Intent(this,TransferQueueActivity.class);PendingIntent show=PendingIntent.getActivity(this,31,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=new Notification.Builder(this,"relay-transfers").setSmallIcon(R.drawable.ic_relay).setContentTitle(idle?"RelayDrop 后台任务":"RelayDrop 正在后台传输").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setContentIntent(show).setOnlyAlertOnce(true).setOngoing(!idle);if(!idle)b.setProgress(100,total>0?(int)Math.min(100,count*100/total):0,total<=0);for(String action:new String[]{idle?RESUME:PAUSE,CANCEL}){PendingIntent pi=PendingIntent.getForegroundService(this,action.hashCode(),new Intent(this,UploadQueueService.class).setAction(action),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);b.addAction(new Notification.Action.Builder(null,RESUME.equals(action)?"恢复任务":PAUSE.equals(action)?"暂停上传":"取消任务",pi).build());}return b.build();}
  private static String safeName(String name){if(name==null)name="分享文件";name=name.replaceAll("[\\x00-\\x1f\\x7f/\\\\]","_").trim();if(name.isEmpty()||name.equals(".")||name.equals(".."))name="分享文件";if(name.length()>240){name=name.substring(0,240);if(Character.isHighSurrogate(name.charAt(239)))name=name.substring(0,239);}return name;}
  static String message(Exception error){String message=error.getMessage();return message==null||message.matches("[\\x00-\\x7f]*")?"操作未完成，请检查网络、原件授权或中转站状态。":message;}
  @Override public void onTimeout(int startId,int type){commands.execute(()->{try{command(PAUSE,null);}catch(Exception ignored){}notifications.notify(NOTICE,notice("系统已暂停长时间后台传输；打开应用后可恢复。",0,0,true));stopSelf();});}
  @Override public IBinder onBind(Intent intent){return null;}
  @Override public void onDestroy(){destroyed=true;ShareTransport client=active;if(client!=null)client.cancel();InputStream input=activeInput;if(input!=null)new Thread(()->{try{input.close();}catch(Exception ignored){}}).start();synchronized(signal){signal.notifyAll();}try{if(connectivity!=null&&network!=null)connectivity.unregisterNetworkCallback(network);}catch(Exception ignored){}if(wake!=null&&wake.isHeld())wake.release();commands.shutdown();super.onDestroy();}
}
